import{c as a,Q as t,j as n,m as i}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"GetMeanMaxMinTmpSize","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetMeanMaxMinTmpSize","slug":"getmeanmaxmintmpsize"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/归约操作/Mean接口/GetMeanMaxMinTmpSize.md","filePath":"api/SIMD-API/高阶API/归约操作/Mean接口/GetMeanMaxMinTmpSize.md"}'),s={name:"api/SIMD-API/高阶API/归约操作/Mean接口/GetMeanMaxMinTmpSize.md"};function l(p,e,d,r,o,c){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="getmeanmaxmintmpsize" tabindex="-1">GetMeanMaxMinTmpSize <a class="header-anchor" href="#getmeanmaxmintmpsize" aria-label="Permalink to &quot;GetMeanMaxMinTmpSize&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>kernel侧Mean接口的计算需要开发者预留/申请临时空间，本接口用于在host侧获取预留/申请的最大最小临时空间大小，开发者基于此范围选择合适的空间大小作为Tiling参数传递到kernel侧使用。</p><ul><li>为保证功能正确，预留/申请的临时空间大小不能小于最小临时空间大小；</li><li>在最小临时空间-最大临时空间范围内，随着临时空间增大，kernel侧接口计算性能会有一定程度的优化提升。为了达到更好的性能，开发者可以根据实际的内存使用情况进行空间预留/申请。该接口<strong>最大临时空间当前等于最小临时空间</strong>。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetMeanMaxMinTmpSize(const uint32_t n, const uint32_t srcTypeSize, const uint32_t accTypeSize, const bool isReuseSource, uint32_t&amp; maxSize, uint32_t&amp; minSize)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 接口参数列表</p><table tabindex="0"><thead><tr><th>接口</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>n</td><td>输入</td><td>输入数据每行的实际计算个数。</td></tr><tr><td>srcTypeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。比如输入的数据类型为half，此处为2。</td></tr><tr><td>accTypeSize</td><td>输入</td><td>accType的数据类型大小，单位为字节，accType参数说明可参考Mean接口参数说明。</td></tr><tr><td>isReuseSource</td><td>输入</td><td>是否复用源操作数输入的空间，与Mean接口一致。此处为预留参数。</td></tr><tr><td>maxSize</td><td>输出</td><td>Mean接口能完成计算所需的最大临时空间大小，超出该值的空间不会被该接口使用。 说明： maxSize仅作为参考值，有可能大于Unified Buffer剩余空间的大小，该场景下，开发者需要根据Unified Buffer剩余空间的大小来选取合适的临时空间大小。</td></tr><tr><td>minSize</td><td>输出</td><td>Mean接口能完成计算所需最小临时空间大小。为保证功能正确，接口计算时预留/申请的临时空间不能小于该数值。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 算子输入的数据类型T为half，accType为float，isReuseSource传入默认值false</span></span>
<span class="line"><span>uint32_t n = 3;</span></span>
<span class="line"><span>uint32_t srcTypeSize = 2;</span></span>
<span class="line"><span>uint32_t accTypeSize = 4;</span></span>
<span class="line"><span>uint32_t maxValue = 0;</span></span>
<span class="line"><span>uint32_t minValue = 0;</span></span>
<span class="line"><span>AscendC::GetMeanMaxMinTmpSize(n, srcTypeSize, accTypeSize, false, maxValue, minValue);</span></span></code></pre></div>`,15)])])}const m=a(s,[["render",l]]);export{u as __pageData,m as default};
